load_driver_logic() {
    local payload_func=$1
    local desc=$2

    echo ""
    echo -e "\033[94m╔════════════════════════════════════════════╗\033[0m"
    echo -e "\033[94m检测到内核版本: \033[1;32m$KERNEL_VER\033[0m"
    echo -e "\033[94m匹配分支: \033[1;32m$desc\033[0m"
    echo -e "\033[94m╚════════════════════════════════════════════╝\033[0m"
    echo ""

    $payload_func | base64 -d > "$TEMP_KO" 2>/dev/null
    
    if [ ! -s "$TEMP_KO" ]; then
        echo -e "\033[1;31m错误: 提取失败 (文件为空)！\033[0m"
        exit 1
    fi

    echo -e "\033[94m正在加载驱动...\033[0m"
    dmesg -c >/dev/null 2>&1
    
    if OUTPUT=$(insmod "$TEMP_KO" 2>&1); then
        echo ""
        echo -e "\033[1;32m成功: 驱动已加载！\033[0m"
        echo ""
        exit 0
    else
        echo ""
        echo -e "\033[1;31m哎呀，出问题了...\033[0m"
        echo ""
        echo -e "\033[1;31m>>> insmod 报错:\033[0m"
        echo "$OUTPUT"
        echo ""
        echo -e "\033[1;31m>>> dmesg 日志:\033[0m"
        dmesg | tail -n 10
        echo ""
        exit 1
    fi
}

# --- 主入口 ---
KERNEL_VER=$(uname -r)

case "$KERNEL_VER" in
    # 6.x 系列
    6.12.*)
        load_driver_logic "Load_6_12" "android16-6.12"
        ;;
    6.6.*)
        load_driver_logic "Load_6_6" "android15-6.6"
        ;;
    6.1.*)
        load_driver_logic "Load_6_1" "android14-6.1"
        ;;
    
    # 5.15 系列
    5.15.*)
        load_driver_logic "Load_5_15" "android13-5.15"
        ;;
    
    # 5.10 系列 (匹配内核名中的 android12 或 android13)
    5.10.*android12*)
        load_driver_logic "Load_5_10_android12" "android12-5.10"
        ;;
    5.10.*android13*)
        load_driver_logic "Load_5_10_android13" "android13-5.10"
        ;;
    
    # 5.10 兜底 (如果内核名里没写 android 版本，默认试用 13)
    5.10.*)
        echo -e "\033[1;31m警告: 5.10 内核但未识别到 android12/13 标签。\033[0m"
        echo -e "\033[94m依次尝试 android13 -> android12...\033[0m"
        load_driver_logic "Load_5_10_android13" "android13-5.10 (fallback)"
        ;;
    
    # 其他
    *)
        echo ""
        echo -e "\033[1;31m╔════════════════════════════════════════════╗\033[0m"
        echo -e "\033[1;31m错误: 不支持的内核版本 ($KERNEL_VER)\033[0m"
        echo -e "\033[94m支持的版本: 5.10 / 5.15 / 6.1 / 6.6 / 6.12\033[0m"
        echo -e "\033[1;31m╚════════════════════════════════════════════╝\033[0m"
        echo ""
        exit 1
        ;;
esac
exit 0
